<?php require_once __DIR__.'/includes/auth.php';require_user();$id=(int)($_GET['id']??0);$s=$pdo->prepare("SELECT r.*,e.title,e.event_date,e.start_time,e.venue,e.image_url FROM registrations r JOIN events e ON e.id=r.event_id WHERE r.id=? AND r.user_id=?");$s->execute([$id,$_SESSION['user_id']]);$r=$s->fetch();if(!$r){flash('danger','Ticket not found.');redirect('my-events.php');}$pageTitle='Registration successful';require __DIR__.'/includes/header.php'; ?><section class="section section-soft"><div class="container"><div class="text-center mb-4"><span class="stat-icon mx-auto" style="background:#e3f8ee;color:#147a52"><i class="bi bi-check-lg"></i></span><h1 class="mt-3">Registration successful!</h1><p class="muted">Your place is reserved. Save your ticket for event day.</p></div><div class="ticket"><div class="d-flex justify-content-between align-items-start gap-3"><div><div class="brand"><span class="brand-mark"><i class="bi bi-ticket-perforated-fill"></i></span> CampusPass</div><span class="category-pill mt-3">Digital entry ticket</span><h2 class="h3 mt-3"><?=e($r['title'])?></h2><p class="muted mb-1"><?=e(date('l, M j, Y',strtotime($r['event_date'])))?> · <?=e(date('g:i A',strtotime($r['start_time'])))?></p><p class="muted"><i class="bi bi-geo-alt me-1"></i><?=e($r['venue'])?></p></div><div class="ticket-qr" data-qr-token="<?=e($r['qr_token'])?>" aria-label="QR ticket code"></div></div><hr><div class="row g-3"><div class="col-sm-6"><div class="small muted">PARTICIPANT</div><strong><?=e($_SESSION['user_name'])?></strong></div><div class="col-sm-6"><div class="small muted">REGISTRATION ID</div><strong><?=e($r['registration_code'])?></strong></div><div class="col-sm-6"><div class="small muted">ENTRY CODE</div><strong class="text-primary fs-5"><?=e($r['entry_code'])?></strong></div><div class="col-sm-6"><div class="small muted">TICKET STATUS</div><span class="status-pill status-published">Valid</span></div></div><p class="small muted mt-4 mb-0">QR code contains an opaque ticket token, not your personal details. Keep this ticket private.</p></div><div class="d-flex justify-content-center gap-2 flex-wrap mt-4"><a class="btn btn-primary" href="ticket.php?id=<?=$id?>"><i class="bi bi-download me-1"></i> View / Print ticket</a><a class="btn btn-outline-primary" href="my-events.php">My events</a><a class="btn btn-link" href="index.php">Back to home</a></div></div></section><script src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js"></script><script src="assets/js/ticket.js"></script><?php require __DIR__.'/includes/footer.php'; ?>
